/* СГЕНЕРИРОВАНО `npm run models -- --write`. Руками не править. */

/**
 * Геометрия принятых моделей набора Low Poly Fox Model (не объявлена; только прототип до подтверждения автора, см. assets/LICENSES.md),
 * запечённая по §6.1: без текстур, цвет — слот палитры на треугольник.
 * Позиции упакованы в 16 бит на ось в габаритах модели (min/max).
 */
export interface FoxModel {
  readonly tris: number;
  readonly verts: number;
  /** Габарит позы привязки: в нём квантованы позиции. */
  readonly min: readonly [number, number, number];
  readonly max: readonly [number, number, number];
  /** base64 Int16Array: 3 числа на вершину. */
  readonly pos: string;
  /** base64 Uint16Array: 3 индекса на треугольник. */
  readonly idx: string;
  /** base64 Uint8Array: индекс в FOX_SLOTS, один на треугольник.
   *  Вершина ломается по слоту, поэтому цвет вершины — цвет её треугольника. */
  readonly slot: string;
}

/** Порядок слотов — контракт с render/palette.ts. */
export const FOX_SLOTS = [
  'дерево-тень',
  'дерево',
  'пламя',
  'уголь',
  'земля',
  'соль-тень',
  'соль',
  'соль-свет',
] as const;

export const FOX_MODELS = {
  'fox': {
    tris: 2134,
    verts: 4349,
    min: [-0.819, -2.203, -3.604],
    max: [0.712, 1.374, 3.518],
    pos: '',
    idx: '',
    slot: '',
  },
} satisfies Record<string, FoxModel>;

export type FoxModelName = keyof typeof FOX_MODELS;
